def update(path, id_column, fact_column):
    with path.open(encoding="utf-8-sig", newline="") as source:
        rows = list(csv.DictReader(source))
        fields = list(rows[0])
    changed = []
    for row in rows:
        case_id = row[id_column]
        if case_id not in OVERRIDES:
            continue
        row[fact_column] = OVERRIDES[case_id]
        if "clean_fact_length" in row:
            row["clean_fact_length"] = str(len(row[fact_column]))
        if "fact_length" in row:
            row["fact_length"] = str(len(row[fact_column]))
        if "review_flags" in row:
            row["review_flags"] = "最终事实清洗复核"
        if "locate_method" in row:
            row["locate_method"] = "manual_final_cleaning"
        changed.append(case_id)
    with path.open("w", encoding="utf-8-sig", newline="") as target:
        writer = csv.DictWriter(target, fieldnames=fields)
        writer.writeheader()
        writer.writerows(rows)
    return changed


changed = update(INITIAL, "id", "clean_fact") + update(SUPPLEMENTAL, "candidate_id", "fact_summary")
missing = sorted(set(OVERRIDES) - set(changed))
if missing:
    raise RuntimeError(f"Override IDs not found: {missing}")
print("updated", len(changed), sorted(changed))
